const responses = await Promise.all(Array.from({ length: 2 }, () => fetch('http://localhost:3987/').then((response) => response.text())))
for (const [index, html] of responses.entries()) {
  const values = html.match(/Request ([\\da-f-]{36}) generated at ([\\dTZ:.+-]+) \\(sample ([\\d.]+)\\)/)
  if ("'!html.includes('"'<nav><a href=\"/\">Operations</a></nav>') || "'!html.includes('"'Deployment health') || "'!values) {
    throw new Error(`Request ${index + 1} missing navigation, page content, or metadata`)
  }
  console.log(`Request ${index + 1}: ${values[1]}, ${values[2]}, ${values[3]}`)
}
const requestIds = responses.map((html) => html.match(/Request (['"\\da-f-]{36})/)[1])
if (new Set(requestIds).size "'!== requestIds.length) throw new Error('"'Request identifiers did not change')
console.log('Navigation, page content, and fresh request metadata verified')
JS"

